# Portable October 13 replication. Run from the repository root; see docs/SIMULATIONS.txt.
## Part R summary (free observation variance): analytic intervals on all datasets, bootstrap on those with draws; paired
## comparison with Part Q (same datasets and resamples, sigma_eps2 fixed at 400) from part_q_raw.rds and results/simulation/boot_b999/posvar_tau*/.
tg <- readRDS("results/simulation/tables/expected_likelihood_target_free_r.rds")$free; tgq <- readRDS("results/simulation/tables/expected_likelihood_targets.rds")$posvar; beta0 <- tgq$generating$beta; pn <- names(beta0); p <- 6; q_t <- qt(.975, 43); q_n <- qnorm(.975); options(width = 250)
pct <- function(d) list(lo = apply(d, 2, quantile, .025, na.rm = TRUE), hi = apply(d, 2, quantile, .975, na.rm = TRUE)); rows <- list(); diag <- list()
for (tau in c(0, 0.4)) { fs <- list.files(sprintf("results/simulation/freevar/tau%s", tau), "^m[0-9]+\\.rds$", full.names = TRUE); z <- lapply(fs, readRDS); ok <- sapply(z, function(x) !x$err && !is.null(x$se)); z <- z[ok]; if (!length(z)) next; target <- if (tau == 0) beta0 else tg$beta
  est <- t(sapply(z, `[[`, "beta")); ms <- sapply(z, `[[`, "m"); r_hat <- sapply(z, `[[`, "sigma_eps2"); q_hat <- sapply(z, `[[`, "sigma_eta2"); zb <- z[sapply(z, function(x) !is.null(x$draws))]
  diag[[as.character(tau)]] <- data.frame(tau = tau, n_fit = length(z), n_err = sum(!ok), not_converged = sum(!sapply(z, `[[`, "conv")), constrained = sum(sapply(z, `[[`, "status") == "constrained"), median_iter = median(sapply(z, `[[`, "iter")), r_mean = mean(r_hat), r_sd = sd(r_hat), r_min = min(r_hat), q_mean = mean(q_hat), min_eig_min = min(sapply(z, `[[`, "min_eig")), n_boot = length(zb),
    boot_refits = sum(sapply(zb, function(x) nrow(x$boot_diag))), boot_nonconv = sum(sapply(zb, function(x) sum(!x$boot_diag$converged, na.rm = TRUE))), boot_constrained = sum(sapply(zb, function(x) sum(x$boot_diag$status == "constrained", na.rm = TRUE))), boot_attempt2 = sum(sapply(zb, function(x) sum(x$boot_diag$attempt == 2))), boot_unresolved = sum(sapply(zb, `[[`, "n_unresolved")), boot_r_min = min(sapply(zb, function(x) min(x$boot_diag$sigma_eps2, na.rm = TRUE))), median_minutes = median(sapply(zb, `[[`, "minutes")))
  ## Part Q paired (fixed r) on the same datasets
  rq <- readRDS("results/simulation/tables/part_q_raw.rds")$raw[[as.character(tau)]]; estq <- t(sapply(rq[ms], `[[`, "beta")); targetq <- if (tau == 0) beta0 else tgq$beta_star
  if (length(zb)) { lo <- t(sapply(zb, function(x) pct(x$draws)$lo)); hi <- t(sapply(zb, function(x) pct(x$draws)$hi)); mb <- sapply(zb, `[[`, "m"); bq <- lapply(mb, function(m) readRDS(sprintf("results/simulation/boot_b999/posvar_tau%s/m%03d.rds", tau, m))); loq <- t(sapply(bq, function(x) pct(x$draws)$lo)); hiq <- t(sapply(bq, function(x) pct(x$draws)$hi)) }
  for (j in seq_len(p)) { row <- data.frame(tau = tau, parameter = pn[j], generating = beta0[j], target_free = target[j], target_fixed = targetq[j], n_fit = nrow(est), mean_est = mean(est[, j]), bias_vs_target = mean(est[, j]) - target[j], emp_sd = sd(est[, j]), emp_sd_fixed_same = sd(estq[, j]), corr_free_fixed = cor(est[, j], estq[, j]))
    for (k in c("model", "cr0", "md")) { s <- sapply(z, function(x) x$se[[k]][pn[j]]); crit <- if (k == "model") q_n else q_t; row[[paste0("se_", k)]] <- mean(s, na.rm = TRUE); row[[paste0("cov_", k)]] <- mean(abs(est[, j] - target[j]) <= crit * s, na.rm = TRUE); row[[paste0("medlen_", k)]] <- median(2 * crit * s, na.rm = TRUE); sq <- sapply(rq[ms], function(x) x$se[[k]][j]); row[[paste0("cov_", k, "_fixed_same")]] <- mean(abs(estq[, j] - targetq[j]) <= crit * sq, na.rm = TRUE) }
    row$n_boot <- length(zb); if (length(zb)) { row$cov_boot <- mean(target[j] >= lo[, j] & target[j] <= hi[, j]); row$medlen_boot <- median(hi[, j] - lo[, j]); row$se_boot <- mean(sapply(zb, function(x) sd(x$draws[, j], na.rm = TRUE))); row$cov_boot_fixed_same <- mean(targetq[j] >= loq[, j] & targetq[j] <= hiq[, j]); row$medlen_boot_fixed_same <- median(hiq[, j] - loq[, j]) }
    rows[[length(rows) + 1]] <- row } }
df <- do.call(rbind, rows); rownames(df) <- NULL; dg <- do.call(rbind, diag); write.csv(df, "results/simulation/tables/part_r_summary.csv", row.names = FALSE); write.csv(dg, "results/simulation/tables/part_r_diagnostics.csv", row.names = FALSE)
print(df[, c("tau", "parameter", "target_free", "target_fixed", "bias_vs_target", "emp_sd", "emp_sd_fixed_same", "se_model", "se_cr0", "se_md", "se_boot", "cov_model", "cov_cr0", "cov_md", "cov_boot", "n_boot", "cov_cr0_fixed_same", "cov_boot_fixed_same", "medlen_cr0", "medlen_boot", "medlen_boot_fixed_same")], digits = 3, row.names = FALSE); print(dg, digits = 4, row.names = FALSE)
